SELECT b.SEC_SNAME AS `股票名称`, b.COMB_SYMBOL AS `股票代码`, a.CHANGEDATE AS `变动日期`, a.CHNG_REAS_NAME AS `变动原因`, ROUND(a.TOTAL / 100000000, 2) AS `总股本(亿)`, ROUND(a.H_SHR / 100000000, 2) AS `H股(亿)` FROM STK_SHR_STRU a JOIN GET_A_SEC_CODE b ON a.COMCODE = b.COMCODE WHERE a.ISVALID = 1 AND b.ISVALID = 1 AND b.SEC_SNAME LIKE '%恒瑞医药%' AND a.CHANGEDATE >= '2025-01-01' AND a.CHANGEDATE <= '2025-06-30' AND a.TOTAL IS NOT NULL ORDER BY a.CHANGEDATE ASC;
